// Scrabble PT Study Transcript
// End-of-game transcript generated by Jeeves

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { FileText, Download, Save, Loader2, Sparkles, BookOpen, Copy, Check } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import type { StudyLogEntry } from './StudyLog';
import type { SelectedVerse } from './VerseSelectionScreen';

interface StudyTranscriptProps {
  entries: StudyLogEntry[];
  seedVerse?: SelectedVerse | null;
  totalScore: number;
  playerCount: number;
  onSave?: (transcript: string) => void;
}

export function StudyTranscript({
  entries,
  seedVerse,
  totalScore,
  playerCount,
  onSave,
}: StudyTranscriptProps) {
  const [transcript, setTranscript] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [copied, setCopied] = useState(false);

  // Generate transcript with Jeeves
  const generateTranscript = async () => {
    if (entries.length === 0) {
      toast.error('No entries to generate transcript from');
      return;
    }

    setIsGenerating(true);

    try {
      // Build the prompt for Jeeves
      const entriesText = entries.map((e, i) =>
        `${i + 1}. ${e.playerName} applied "${e.cardName}" (${e.cardCode})${e.isChristConnection ? ' [Christ Connection]' : ''}:\n   "${e.explanation}"`
      ).join('\n\n');

      const prompt = seedVerse
        ? `Create a cohesive Bible study transcript from these Phototheology principle applications to ${seedVerse.reference} ("${seedVerse.text}"):\n\n${entriesText}\n\nWrite a flowing, insightful summary that weaves together all the contributions into a unified study. Include the verse reference, highlight key insights, and show how the principles build on each other. Make it suitable for sharing or future reference.`
        : `Create a cohesive study transcript from these Phototheology principle connections:\n\n${entriesText}\n\nWrite a flowing summary that weaves together all the contributions. Highlight key insights and show how the principles connect.`;

      const { data, error } = await supabase.functions.invoke('jeeves', {
        body: {
          message: prompt,
          context: 'scrabble_transcript',
        },
      });

      if (error) throw error;

      const generatedTranscript = data?.response || data?.message || 'Unable to generate transcript.';

      // Add header and footer
      const fullTranscript = `# Scrabble PT Study Transcript
${seedVerse ? `\n## ${seedVerse.reference}\n> "${seedVerse.text}"\n` : ''}
**Players:** ${playerCount} | **Total Score:** ${totalScore} | **Contributions:** ${entries.length}

---

${generatedTranscript}

---

*Generated by Jeeves AI from Scrabble PT game session*
*${new Date().toLocaleDateString()} at ${new Date().toLocaleTimeString()}*`;

      setTranscript(fullTranscript);
    } catch (err: any) {
      console.error('Error generating transcript:', err);

      // Fallback: create a simple transcript without AI
      const fallbackTranscript = createFallbackTranscript();
      setTranscript(fallbackTranscript);
      toast.info('Created basic transcript (AI unavailable)');
    } finally {
      setIsGenerating(false);
    }
  };

  // Fallback transcript without AI
  const createFallbackTranscript = (): string => {
    const entriesText = entries.map((e, i) =>
      `### ${i + 1}. ${e.cardName} (${e.cardCode}) - by ${e.playerName}${e.isChristConnection ? ' ✝️' : ''}

${e.explanation}

*+${e.points} points*`
    ).join('\n\n---\n\n');

    return `# Scrabble PT Study Transcript
${seedVerse ? `\n## ${seedVerse.reference}\n> "${seedVerse.text}"\n` : ''}
**Players:** ${playerCount} | **Total Score:** ${totalScore} | **Contributions:** ${entries.length}

---

${entriesText}

---

*Scrabble PT game session*
*${new Date().toLocaleDateString()} at ${new Date().toLocaleTimeString()}*`;
  };

  // Copy to clipboard
  const handleCopy = async () => {
    if (!transcript) return;

    try {
      await navigator.clipboard.writeText(transcript);
      setCopied(true);
      toast.success('Copied to clipboard!');
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      toast.error('Failed to copy');
    }
  };

  // Download as file
  const handleDownload = () => {
    if (!transcript) return;

    const blob = new Blob([transcript], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `scrabble-pt-study-${new Date().toISOString().split('T')[0]}.md`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    toast.success('Downloaded!');
  };

  // Save to suite
  const handleSave = () => {
    if (!transcript || !onSave) return;
    onSave(transcript);
    toast.success('Saved to your studies!');
  };

  // Auto-generate on mount if we have entries
  useEffect(() => {
    if (entries.length > 0 && !transcript && !isGenerating) {
      generateTranscript();
    }
  }, [entries.length]);

  return (
    <Card className="w-full max-w-2xl mx-auto">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <FileText className="h-5 w-5 text-primary" />
          Study Transcript
        </CardTitle>
        <CardDescription>
          A cohesive summary of your Scrabble PT session
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Generate button */}
        {!transcript && !isGenerating && (
          <Button onClick={generateTranscript} className="w-full">
            <Sparkles className="mr-2 h-4 w-4" />
            Generate Transcript with Jeeves
          </Button>
        )}

        {/* Loading state */}
        {isGenerating && (
          <div className="flex flex-col items-center justify-center py-8 gap-4">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
            <p className="text-sm text-muted-foreground">Jeeves is writing your transcript...</p>
          </div>
        )}

        {/* Transcript display */}
        {transcript && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-4"
          >
            {/* Transcript content */}
            <div className="p-4 bg-muted rounded-lg max-h-96 overflow-y-auto">
              <pre className="whitespace-pre-wrap text-sm font-sans leading-relaxed">
                {transcript}
              </pre>
            </div>

            {/* Action buttons */}
            <div className="flex flex-wrap gap-2">
              <Button variant="outline" onClick={handleCopy}>
                {copied ? <Check className="mr-2 h-4 w-4" /> : <Copy className="mr-2 h-4 w-4" />}
                {copied ? 'Copied!' : 'Copy'}
              </Button>
              <Button variant="outline" onClick={handleDownload}>
                <Download className="mr-2 h-4 w-4" />
                Download
              </Button>
              {onSave && (
                <Button onClick={handleSave}>
                  <Save className="mr-2 h-4 w-4" />
                  Save to Suite
                </Button>
              )}
              <Button variant="ghost" onClick={generateTranscript}>
                <Sparkles className="mr-2 h-4 w-4" />
                Regenerate
              </Button>
            </div>
          </motion.div>
        )}

        {/* Stats */}
        <div className="flex items-center justify-center gap-6 pt-4 border-t text-sm text-muted-foreground">
          <span>{entries.length} contributions</span>
          <span>{playerCount} player{playerCount !== 1 ? 's' : ''}</span>
          <span className="text-yellow-500 font-medium">{totalScore} total points</span>
        </div>
      </CardContent>
    </Card>
  );
}
